uint getDebMode(uint numDfc)
{
    uint debMode;
    if (numDfc < DSM_ctCfgPreDebTiMax)
    {

        debMode = 0u;
    }
    else if (numDfc < DSM_ctCfgPreDebEvntMax)
    {

        debMode = 1u;
    }
    else if (numDfc < DSM_ctCfgPreDebTiUDMax)
    {

        debMode = 2u;
    }
    else if (numDfc < DSM_ctCfgPreDebEvntUDMax)
    {

        debMode = 3u;
    }
    else if (numDfc < DSM_ctCfgPreDebTiUDSmMax)
    {

        debMode = 4u;
    }
    else if (numDfc < DSM_ctCfgPreDebEvntUDSmMax)
    {

        debMode = 5u;
    }
    else if (numDfc < DSM_ctCfgPreDebTiSmMax)
    {

        debMode = 6u;
    }
    else if(numDfc < DSM_ctCfgPreDebEvntSmMax)
    {

        debMode = 7u;
    }
    else
    {

        debMode = 8u;
    }
    return debMode;
}
